package com.gestionmedica.service;
import com.gestionmedica.exception.ApiException; import com.gestionmedica.model.Models.Patient; import com.gestionmedica.persistence.entity.UserEntity; import com.gestionmedica.persistence.repository.UserRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import javax.crypto.SecretKeyFactory; import javax.crypto.spec.PBEKeySpec; import java.security.SecureRandom; import java.util.Base64; import java.util.Locale; import java.util.UUID; import java.util.concurrent.ConcurrentHashMap; import java.util.concurrent.ConcurrentMap;
@Service public class AuthService {
 private final UserRepository users; private final PatientService patients; private final SecureRandom random=new SecureRandom(); private final ConcurrentMap<String,String> tokens=new ConcurrentHashMap<>();
 public AuthService(UserRepository users,PatientService patients){this.users=users;this.patients=patients;}
 @Transactional public synchronized String register(String patientId,String email,String password){Patient p=patients.get(patientId);if(!p.email().equalsIgnoreCase(email))throw ApiException.badRequest("El correo no coincide con el paciente");String key=key(email);if(users.existsById(key))throw ApiException.conflict("La cuenta ya está registrada");users.save(new UserEntity(key,p.id(),hash(password)));return login(email,password);}
 @Transactional(readOnly=true) public String login(String email,String password){String key=key(email);UserEntity account=users.findById(key).orElse(null);if(account==null||!verify(password,account.getPasswordHash()))throw ApiException.unauthorized("Credenciales inválidas");String token=UUID.randomUUID()+"."+UUID.randomUUID();tokens.put(token,account.getPatientId());return token;}
 public String patientForToken(String token){String id=tokens.get(token);if(id==null)throw ApiException.unauthorized("Token inválido o vencido");return id;}
 private String key(String email){return email.trim().toLowerCase(Locale.ROOT);}
 private String hash(String password){byte[] salt=new byte[16];random.nextBytes(salt);return Base64.getEncoder().encodeToString(salt)+":"+Base64.getEncoder().encodeToString(derive(password,salt));}
 private boolean verify(String password,String saved){try{String[] parts=saved.split(":");return java.security.MessageDigest.isEqual(Base64.getDecoder().decode(parts[1]),derive(password,Base64.getDecoder().decode(parts[0])));}catch(RuntimeException e){return false;}}
 private byte[] derive(String password,byte[] salt){PBEKeySpec spec=new PBEKeySpec(password.toCharArray(),salt,210_000,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();}catch(Exception e){throw new IllegalStateException("Password hashing unavailable",e);}finally{spec.clearPassword();}}
}
